test "t0" {
    assert (find(lambda (m: Any) { (m.name == 'Mighty'); }, []) == None);;
}

test "t1" {
    assert (
        find(lambda (e: Any) { (e == 'Mighty'); }, ['Tails', 'Heads', 'Mighty'])
        == 'Mighty'
    );;
}

test "t2" {
    assert (find(lambda (x: Any) { (x == 1); }, [1, 2, 3]) == 1);;
}

test "t3" {
    assert (find(lambda (m: Any) { (m == 2); }, `list(range(10))) == 2);;
}

